const input = $input.first().json;
const event = input.body ?? input;
const allowed = ['order.created', 'payment.simulated', 'order.status_changed', 'stock.updated', 'support.requested', 'incident.created', 'agent.approved'];
if (!event.eventId || String(event.eventId).length > 120) throw new Error('eventId obligatorio.');
if (!allowed.includes(event.type)) throw new Error('Tipo de evento no permitido.');
if (!event.entity?.type || !event.entity?.id || !event.occurredAt) throw new Error('Faltan entidad o fecha.');
if (Number.isNaN(Date.parse(event.occurredAt))) throw new Error('occurredAt no es una fecha válida.');
if (!event.data || typeof event.data !== 'object' || Array.isArray(event.data)) throw new Error('data debe ser un objeto.');
const route = ['order.created', 'payment.simulated'].includes(event.type) ? 'order' : ['order.status_changed', 'stock.updated'].includes(event.type) ? 'change' : ['support.requested', 'incident.created'].includes(event.type) ? 'support' : 'approved';
return [{ json: { ...event, route, data: event.data } }];

