={{ (() => {
  const p = String($fromAI('priority', 'Prioridad exacta: baja, media, alta o urgente', 'string')).toLowerCase();
  const c = $fromAI('consultedData', 'Objeto JSON con los datos obtenidos de la herramienta de consulta (incidencia y pedidos recientes), no texto suelto', 'json');
  const conf = Number($fromAI('confidence', 'Número entre 0 y 1, por ejemplo 0.8', 'number'));
  return {
    sourceEventId: String($fromAI('sourceEventId', 'eventId exacto del evento recibido, por ejemplo incident:10:support-requested', 'string')).slice(0, 120),
    incidentId: $fromAI('incidentId', 'ID numérico de la incidencia', 'number'),
    caseType: String($fromAI('caseType', 'Categoría corta de la incidencia, máximo 60 caracteres', 'string')).slice(0, 80),
    consultedData: (c && typeof c === 'object') ? c : { resumen: String(c ?? '') },
    proposedAction: String($fromAI('proposedAction', 'Una sola acción interna en una frase de menos de 100 caracteres: clasificar incidencia, crear tarea de soporte o preparar notificación interna', 'string')).slice(0, 120),
    rationale: String($fromAI('rationale', 'Justificación breve basada en los datos consultados', 'string')).slice(0, 2000),
    confidence: Number.isFinite(conf) ? Math.min(1, Math.max(0, conf)) : 0.5,
    priority: ['baja', 'media', 'alta', 'urgente'].includes(p) ? p : 'media',
    risks: String($fromAI('risks', 'Riesgos o advertencias, nunca vacío', 'string') || 'Sin riesgos identificados; revisar manualmente.').slice(0, 2000)
  };
})() }}
